#!/usr/bin/env node
/**
 * Records real Code View text into test/fixtures/code-view: documents are built
 * in the Grist at GRIST_URL, the text is generated by that Grist's own gencode.py
 * and saved beside the columns it must be read back as.
 *
 *   GRIST_SANDBOX_DIR=<grist-core>/sandbox/grist GRIST_PYTHON=<python> GRIST_VERSION=1.7.20 \
 *     node test/grist/record-code-view.mjs
 *
 * `node test/grist/record-code-view.mjs strings` records only strings-<GRIST_VERSION>: run it against each version of
 * Grist that writes the strings of a formula in a way of its own.
 */
import { execFileSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { instance, buildSource, column } from "./support.mjs";
import { zipRows } from "../../js/schema.js";
import { SPEC, STRING_FORMULAS } from "./spec.mjs";

const OUT = new URL("../fixtures/code-view/", import.meta.url);
const HELPER = new URL("./code_view.py", import.meta.url).pathname;

async function record(name, doc) {
  const [tables, columns] = await Promise.all([doc.fetchTable("_grist_Tables"), doc.fetchTable("_grist_Tables_column")]);
  const text = execFileSync(process.env.GRIST_PYTHON ?? "python3", [HELPER], { input: JSON.stringify({ tables, columns }), encoding: "utf8" });
  const hidden = (col) => col.colId === "manualSort" || col.colId.startsWith("gristHelper_");
  const expected = { grist: process.env.GRIST_VERSION ?? "unknown", tables: {} };
  for (const table of zipRows(tables).filter((row) => !row.summarySourceTable)) {
    expected.tables[table.tableId] = zipRows(columns)
      .filter((col) => col.parentId === table.id && !hidden(col))
      .sort((a, b) => Number(a.isFormula) - Number(b.isFormula) || a.parentPos - b.parentPos)
      .map((col) => [col.colId, col.type, Boolean(col.isFormula || col.formula)]);
  }
  mkdirSync(OUT, { recursive: true });
  writeFileSync(new URL(`${name}.py`, OUT), text);
  const tableLines = Object.entries(expected.tables).map(
    ([id, cols]) => `    ${JSON.stringify(id)}: [\n${cols.map((col) => `      ${JSON.stringify(col)}`).join(",\n")}\n    ]`
  );
  writeFileSync(new URL(`${name}.json`, OUT), `{\n  "grist": ${JSON.stringify(expected.grist)},\n  "tables": {\n${tableLines.join(",\n")}\n  }\n}\n`);
  console.log(`${name}: ${Object.keys(expected.tables).length} tables, ${text.split("\n").length} lines`);
}

if (process.argv[2] === "strings") {
  const strings = await instance.newDoc("code view: strings");
  await buildSource(strings, { Strings: Object.entries(STRING_FORMULAS).map(([id, formula]) => ({ id, type: "Text", formula })) });
  await record(`strings-${process.env.GRIST_VERSION ?? "unknown"}`, strings);
  await instance.cleanup();
  process.exit(0);
}

const everything = await instance.newDoc("code view: every column");
await buildSource(everything, SPEC);
await record("every-column", everything);

const features = await instance.newDoc("code view: features");
await features.apply([
  ["AddTable", "People", [column("Name"), column("Age", "Int"), column("Born", "DateTime:Europe/Paris")]],
  ["AddTable", "Pets", [column("Owner", "Ref:People"), column("Friends", "RefList:People"), column("Photo", "Attachments")]],
]);
await features.apply([
  ["AddColumn", "People", "Double", { type: "Numeric", isFormula: true, formula: "$Age * 2" }],
  ["AddColumn", "People", "Stamp", { type: "Text", isFormula: false, formula: "'hello'" }],
  ["AddColumn", "People", "Anything", { type: "Any", isFormula: true, formula: "$Name" }],
  ["AddReverseColumn", "Pets", "Owner"],
]);
const [people] = zipRows(await features.fetchTable("_grist_Tables")).filter((row) => row.tableId === "People");
const age = (await features.columns("People")).find((col) => col.colId === "Age");
await features.apply([["CreateViewSection", people.id, 0, "record", [age.id], null]]);
await record("features", features);

await instance.cleanup();
